UPDATE purchase_order
SET e_id = #{eId}, o_total_quantity = #{oTotalQuantity},
    o_total_price = #{oTotalPrice}, o_time = #{oTime}, o_remark = #{oRemark}
WHERE o_id = #{oId}

UPDATE purchase_order o
SET o_total_quantity = (
    SELECT COALESCE(SUM(d_quantity), 0)
    FROM purchase_detail
    WHERE o_id = #{oId}
),
o_total_price = (
    SELECT COALESCE(SUM(d_quantity * d_price), 0)
    FROM purchase_detail
    WHERE o_id = #{oId}
)
WHERE o_id = #{oId}
